// Helpers shared by the emitters.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';

// The first line of every generated file, in the comment syntax of its language.
export function HEADER(open, close = '') {
  return `${open} Code generated by libs/design/build from libs/design/{tokens,icons,strings}. DO NOT EDIT.${close}`;
}

export function write(path, content) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
}

const h2 = (n) => n.toString(16).padStart(2, '0').toUpperCase();

// #RRGGBB, or #RRGGBBAA when the color is translucent.
export function hex({ r, g, b, a }) {
  return `#${h2(r)}${h2(g)}${h2(b)}${a === 1 ? '' : h2(Math.round(a * 255))}`;
}

export function pascal(s) {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

export function snake(s) {
  return s.replace(/\./g, '_').replace(/[A-Z]/g, (c) => '_' + c.toLowerCase());
}

// A number as the literal of a language: integers stay integers.
export function num(n) {
  return Number.isInteger(n) ? String(n) : String(Math.round(n * 10000) / 10000);
}
